-- ============================================================================
-- CSDL MICROSOFT SQL SERVER: QUẢN LÝ CỐ VẤN HỌC TẬP VÀ CẢNH BÁO HỌC VỤ
-- ĐỒ SỘ 30 LỚP - 1,050 SINH VIÊN - 4 CỐ VẤN - ĐỒNG BỘ 100% QUY CHẾ TÍN CHỈ
-- ============================================================================
USE master;
GO

IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = 'ql_canhbao_hocvu')
BEGIN
    CREATE DATABASE ql_canhbao_hocvu COLLATE Vietnamese_CI_AS;
END
GO

USE ql_canhbao_hocvu;
GO

EXEC sp_msforeachtable 'ALTER TABLE ? NOCHECK CONSTRAINT all';
GO


IF OBJECT_ID('phien_dang_nhap', 'U') IS NOT NULL DROP TABLE phien_dang_nhap;
IF OBJECT_ID('nhat_ky_he_thong', 'U') IS NOT NULL DROP TABLE nhat_ky_he_thong;
IF OBJECT_ID('diem_danh', 'U') IS NOT NULL DROP TABLE diem_danh;
IF OBJECT_ID('chuyen_can_mon_hoc', 'U') IS NOT NULL DROP TABLE chuyen_can_mon_hoc;
IF OBJECT_ID('lich_giang_day', 'U') IS NOT NULL DROP TABLE lich_giang_day;
IF OBJECT_ID('thong_bao', 'U') IS NOT NULL DROP TABLE thong_bao;
IF OBJECT_ID('nhat_ky_tu_van', 'U') IS NOT NULL DROP TABLE nhat_ky_tu_van;
IF OBJECT_ID('canh_bao_hoc_vu', 'U') IS NOT NULL DROP TABLE canh_bao_hoc_vu;
IF OBJECT_ID('ket_qua_hoc_tap', 'U') IS NOT NULL DROP TABLE ket_qua_hoc_tap;
IF OBJECT_ID('sinh_vien', 'U') IS NOT NULL DROP TABLE sinh_vien;
IF OBJECT_ID('lop_hoc', 'U') IS NOT NULL DROP TABLE lop_hoc;
IF OBJECT_ID('mon_hoc', 'U') IS NOT NULL DROP TABLE mon_hoc;
IF OBJECT_ID('co_van_hoc_tap', 'U') IS NOT NULL DROP TABLE co_van_hoc_tap;
IF OBJECT_ID('tai_khoan', 'U') IS NOT NULL DROP TABLE tai_khoan;
IF OBJECT_ID('vai_tro', 'U') IS NOT NULL DROP TABLE vai_tro;
GO

CREATE TABLE vai_tro (
    ma_vai_tro VARCHAR(50) PRIMARY KEY,
    ten_vai_tro NVARCHAR(100) NOT NULL,
    mo_ta NVARCHAR(255)
);
GO

CREATE TABLE co_van_hoc_tap (
    ma_cvht VARCHAR(20) PRIMARY KEY,
    ho_ten NVARCHAR(100) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    so_dien_thoai VARCHAR(20) NOT NULL,
    khoa NVARCHAR(100) NOT NULL
);
GO

CREATE TABLE mon_hoc (
    ma_mon VARCHAR(20) PRIMARY KEY,
    ten_mon NVARCHAR(150) NOT NULL,
    so_tin_chi INT NOT NULL,
    so_tiet INT NOT NULL,
    so_buoi_toi_da_vang INT NOT NULL,
    khoa NVARCHAR(100) NOT NULL
);
GO

CREATE TABLE lop_hoc (
    ma_lop VARCHAR(20) PRIMARY KEY,
    ten_lop NVARCHAR(150) NOT NULL,
    khoa NVARCHAR(100) NOT NULL,
    khoa_hoc INT NOT NULL,
    ma_cvht VARCHAR(20) NOT NULL,
    CONSTRAINT fk_lop_covan FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht)
);
GO

CREATE TABLE sinh_vien (
    ma_sv VARCHAR(20) PRIMARY KEY,
    ho_ten NVARCHAR(100) NOT NULL,
    ngay_sinh DATE NOT NULL,
    gioi_tinh NVARCHAR(10) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,
    so_dien_thoai VARCHAR(20) NOT NULL,
    ma_lop VARCHAR(20) NOT NULL,
    trang_thai VARCHAR(20) DEFAULT 'DANG_HOC',
    tong_tin_chi_tich_luy INT DEFAULT 0,
    nam_thu INT DEFAULT 1,
    CONSTRAINT fk_sinhvien_lop FOREIGN KEY (ma_lop) REFERENCES lop_hoc(ma_lop)
);
GO

CREATE TABLE tai_khoan (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ten_dang_nhap VARCHAR(50) NOT NULL UNIQUE,
    mat_khau VARCHAR(255) NOT NULL,
    ho_ten NVARCHAR(100) NOT NULL,
    email VARCHAR(100) NOT NULL,
    vai_tro VARCHAR(50) NOT NULL,
    ma_ref VARCHAR(50),
    ngay_tao DATETIME DEFAULT GETDATE(),
    CONSTRAINT fk_tk_vaitro FOREIGN KEY (vai_tro) REFERENCES vai_tro(ma_vai_tro)
);
GO

CREATE TABLE chuyen_can_mon_hoc (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ma_sv VARCHAR(20) NOT NULL,
    ma_mon VARCHAR(20) NOT NULL,
    ma_lop VARCHAR(20) NOT NULL,
    hoc_ky INT NOT NULL,
    nam_hoc VARCHAR(20) NOT NULL,
    tong_so_buoi INT NOT NULL,
    so_buoi_co_mat INT DEFAULT 0,
    so_buoi_muon INT DEFAULT 0,
    so_buoi_vang_phep INT DEFAULT 0,
    so_buoi_vang_khong_phep INT DEFAULT 0,
    tong_buoi_vang_quy_doi FLOAT DEFAULT 0,
    ty_le_vang FLOAT DEFAULT 0,
    diem_chuyen_can FLOAT DEFAULT 10,
    trang_thai_du_thi VARCHAR(30) DEFAULT 'DU_DIEU_KIEN',
    ly_do_cam_thi NVARCHAR(255),
    ghi_chu NVARCHAR(255),
    CONSTRAINT fk_cc_sv FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv),
    CONSTRAINT fk_cc_mon FOREIGN KEY (ma_mon) REFERENCES mon_hoc(ma_mon)
);
GO

CREATE TABLE lich_giang_day (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ma_cvht VARCHAR(20) NOT NULL,
    ten_cvht NVARCHAR(100) NOT NULL,
    ma_lop VARCHAR(20) NOT NULL,
    ten_lop NVARCHAR(150) NOT NULL,
    tieu_de NVARCHAR(200) NOT NULL,
    ngay DATE NOT NULL,
    gio_bat_dau VARCHAR(10) NOT NULL,
    gio_ket_thuc VARCHAR(10) NOT NULL,
    dia_diem NVARCHAR(100) NOT NULL,
    hinh_thuc VARCHAR(20) DEFAULT 'TRUC_TIEP',
    loai_buoi VARCHAR(50) DEFAULT 'HOC_CHINH_KHOA',
    trang_thai VARCHAR(30) DEFAULT 'HOAN_THANH',
    ghi_chu NVARCHAR(255),
    CONSTRAINT fk_lich_cvht FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht),
    CONSTRAINT fk_lich_lop FOREIGN KEY (ma_lop) REFERENCES lop_hoc(ma_lop)
);
GO

CREATE TABLE diem_danh (
    id INT IDENTITY(1,1) PRIMARY KEY,
    id_lich INT NOT NULL,
    ma_sv VARCHAR(20) NOT NULL,
    ngay_diem_danh DATE NOT NULL,
    trang_thai VARCHAR(20) DEFAULT 'ON_TIME',
    ghi_chu NVARCHAR(255),
    CONSTRAINT fk_diemdanh_lich FOREIGN KEY (id_lich) REFERENCES lich_giang_day(id),
    CONSTRAINT fk_diemdanh_sv FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv)
);
GO

CREATE TABLE ket_qua_hoc_tap (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ma_sv VARCHAR(20) NOT NULL,
    hoc_ky INT NOT NULL,
    nam_hoc VARCHAR(20) NOT NULL,
    gpa_hoc_ky FLOAT NOT NULL,
    gpa_tich_luy FLOAT NOT NULL,
    so_tin_chi_no INT DEFAULT 0,
    tong_tin_chi_tich_luy INT DEFAULT 0,
    nam_thu INT DEFAULT 1,
    CONSTRAINT fk_kq_sinhvien FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv)
);
GO

CREATE TABLE canh_bao_hoc_vu (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ma_canh_bao VARCHAR(50) NOT NULL UNIQUE,
    ma_sv VARCHAR(20) NOT NULL,
    hoc_ky INT NOT NULL,
    nam_hoc VARCHAR(20) NOT NULL,
    muc_canh_bao VARCHAR(20) NOT NULL,
    gpa_xet_duyet FLOAT NOT NULL,
    ly_do NVARCHAR(255) NOT NULL,
    ngay_quyet_dinh DATE NOT NULL,
    trang_thai_tu_van VARCHAR(30) DEFAULT 'CHUA_TU_VAN',
    CONSTRAINT fk_canhbao_sinhvien FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv)
);
GO

CREATE TABLE nhat_ky_tu_van (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ma_sv VARCHAR(20) NOT NULL,
    ma_cvht VARCHAR(20) NOT NULL,
    id_canh_bao INT,
    ngay_tu_van DATE NOT NULL,
    hinh_thuc NVARCHAR(100) NOT NULL,
    noi_dung NVARCHAR(MAX) NOT NULL,
    nguyen_nhan NVARCHAR(MAX),
    giai_phap NVARCHAR(MAX),
    cam_ket_sinh_vien NVARCHAR(MAX),
    CONSTRAINT fk_nhatky_covan FOREIGN KEY (ma_cvht) REFERENCES co_van_hoc_tap(ma_cvht),
    CONSTRAINT fk_nhatky_sinhvien FOREIGN KEY (ma_sv) REFERENCES sinh_vien(ma_sv)
);
GO

CREATE TABLE thong_bao (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ma_thong_bao VARCHAR(50) NOT NULL UNIQUE,
    tieu_de NVARCHAR(255) NOT NULL,
    noi_dung NVARCHAR(MAX) NOT NULL,
    nhom_rui_ro VARCHAR(50) DEFAULT 'CHUNG',
    ma_lop VARCHAR(20),
    ma_sv VARCHAR(20),
    ngay_gui DATETIME DEFAULT GETDATE(),
    nguoi_gui NVARCHAR(100) NOT NULL,
    so_luong_nhan INT DEFAULT 1,
    trang_thai VARCHAR(20) DEFAULT 'DA_GUI'
);
GO

