INSERT INTO nhat_ky_tu_van ([id], [ma_sv], [ma_cvht], [id_canh_bao], [ngay_tu_van], [hinh_thuc], [noi_dung], [nguyen_nhan], [giai_phap], [cam_ket_sinh_vien]) VALUES
(1, '20200016', 'CV001', 1, '2024-11-21', N'Tư vấn trực tuyến qua Microsoft Teams', N'Sinh viên nghiện game online, thường xuyên trốn học và thức khuya', N'Mất kiểm soát thời gian biểu, sống một mình không có sự quản lý của gia đình', N'Cố vấn liên hệ trực tiếp với phụ huynh để phối hợp quản lý giờ giấc, đưa vào danh sách theo dõi đặc biệt', N'Em xin hứa xóa game trên máy tính, nộp báo cáo điểm danh hàng tuần cho thầy cô'),
(2, '20200017', 'CV001', 2, '2024-11-21', N'Tư vấn trực tuyến qua Microsoft Teams', N'Sinh viên sa sút do đi làm thêm ca đêm quá nhiều, thường xuyên ngủ gật và vắng tiết', N'Đi làm thêm bán thời gian 40h/tuần dẫn đến kiệt sức và bỏ bê việc học', N'Yêu cầu sinh viên giảm giờ làm xuống dưới 15h/tuần, cam kết đi học chuyên cần và lập kế hoạch trả nợ 2 môn', N'Em xin hứa sẽ nghỉ bớt ca làm thêm, đi học đầy đủ đúng giờ và đạt điểm C+ trở lên kỳ tới'),
(3, '20210036', 'CV001', 4, '2024-11-10', N'Gặp trực tiếp tại Văn phòng Cố vấn Khoa', N'Sinh viên sa sút do đi làm thêm ca đêm quá nhiều, thường xuyên ngủ gật và vắng tiết', N'Đi làm thêm bán thời gian 40h/tuần dẫn đến kiệt sức và bỏ bê việc học', N'Yêu cầu sinh viên giảm giờ làm xuống dưới 15h/tuần, cam kết đi học chuyên cần và lập kế hoạch trả nợ 2 môn', N'Em xin hứa sẽ nghỉ bớt ca làm thêm, đi học đầy đủ đúng giờ và đạt điểm C+ trở lên kỳ tới'),
(4, '20210037', 'CV001', 5, '2024-11-23', N'Tư vấn trực tuyến qua Microsoft Teams', N'Sinh viên sa sút do đi làm thêm ca đêm quá nhiều, thường xuyên ngủ gật và vắng tiết', N'Đi làm thêm bán thời gian 40h/tuần dẫn đến kiệt sức và bỏ bê việc học', N'Yêu cầu sinh viên giảm giờ làm xuống dưới 15h/tuần, cam kết đi học chuyên cần và lập kế hoạch trả nợ 2 môn', N'Em xin hứa sẽ nghỉ bớt ca làm thêm, đi học đầy đủ đúng giờ và đạt điểm C+ trở lên kỳ tới'),
(5, '20210059', 'CV001', 6, '2024-11-25', N'Gặp trực tiếp tại Văn phòng Cố vấn Khoa', N'Sinh viên nghiện game online, thường xuyên trốn học và thức khuya', N'Mất kiểm soát thời gian biểu, sống một mình không có sự quản lý của gia đình', N'Cố vấn liên hệ trực tiếp với phụ huynh để phối hợp quản lý giờ giấc, đưa vào danh sách theo dõi đặc biệt', N'Em xin hứa xóa game trên máy tính, nộp báo cáo điểm danh hàng tuần cho thầy cô'),
(6, '20230107', 'CV001', 7, '2024-11-12', N'Gặp trực tiếp tại Văn phòng Cố vấn Khoa', N'Sinh viên nghiện game online, thường xuyên trốn học và thức khuya', N'Mất kiểm soát thời gian biểu, sống một mình không có sự quản lý của gia đình', N'Cố vấn liên hệ trực tiếp với phụ huynh để phối hợp quản lý giờ giấc, đưa vào danh sách theo dõi đặc biệt', N'Em xin hứa xóa game trên máy tính, nộp báo cáo điểm danh hàng tuần cho thầy cô'),
