INSERT INTO thong_bao ([id], [ma_thong_bao], [tieu_de], [noi_dung], [nhom_rui_ro], [ma_lop], [ma_sv], [ngay_gui], [nguoi_gui], [so_luong_nhan], [trang_thai]) VALUES
(1, 'TB001', N'Thông báo Lịch Sinh hoạt Cố vấn Học tập Định kỳ Tháng 10/2024', N'Kính mời toàn thể sinh viên các lớp thuộc 4 khoa (CNTT, Ô tô, QTKD, Điện - Điện tử) tham gia đầy đủ buổi sinh hoạt cố vấn học tập định kỳ theo thời khóa biểu.', 'CHUNG', NULL, NULL, '2024-10-01 08:30:00', N'Phòng Đào Tạo & QLSV EAUT', 1050, 'DA_GUI'),
(2, 'TB002', N'Cảnh báo Nguy cơ Cấm thi Kết thúc Học phần Học kỳ 1 Năm học 2024-2025', N'Hệ thống tự động ghi nhận các trường hợp vắng học tiếp cận ngưỡng 20%. Đề nghị các bạn sinh viên rà soát lại số buổi chuyên cần trên hệ thống.', 'CHUYEN_CAN', 'DCCNTT14A', NULL, '2024-11-15 09:00:00', N'TS. Đinh Văn Phong - CVHT', 35, 'DA_GUI'),
(3, 'TB003', N'Quyết định Cảnh báo Học vụ Mức 1 & 2 Học kỳ 1', N'Phòng Đào tạo công bố danh sách sinh viên bị cảnh báo học vụ. Yêu cầu sinh viên liên hệ ngay Cố vấn học tập để thực hiện tư vấn và ký cam kết cải thiện.', 'CANH_BAO', NULL, NULL, '2024-11-20 14:00:00', N'Ban Giám Hiệu & Phòng Đào Tạo', 180, 'DA_GUI'),
(4, 'TB004', N'Kế hoạch Tổ chức Thi Kết thúc Học phần và Điều kiện Dự thi', N'Điều kiện tiên quyết để được dự thi: Tỷ lệ vắng mặt không quá 20% tổng số buổi tín chỉ. Sinh viên bị cấm thi phải đăng ký học lại vào học kỳ phụ.', 'CHUNG', NULL, NULL, '2024-12-05 10:15:00', N'Phòng Khảo Thí & Đảm Bảo CL', 1050, 'DA_GUI'),
(5, 'TB005', N'Nhắc nhở Chuyên cần & Điểm danh Môn Lập trình Java IT201 Lớp DCCNTT14A', N'Hiện tại có một số sinh viên vắng từ 3-4 buổi môn Lập trình Java. Cố vấn học tập yêu cầu các bạn gặp trực tiếp vào thứ 5 tuần này.', 'CHUYEN_CAN', 'DCCNTT14A', NULL, '2024-11-28 16:30:00', N'TS. Đinh Văn Phong', 35, 'DA_GUI'),
(6, 'TB006', N'Thông báo Lịch Thực hành Xưởng Chẩn đoán Ô tô Lớp DCOTO14A', N'Sinh viên mang đầy đủ bảo hộ lao động khi vào xưởng động cơ. Sinh viên vắng không có lý do sẽ bị trừ điểm chuyên cần nghiêm khắc.', 'CHUYEN_CAN', 'DCOTO14A', NULL, '2024-11-10 08:00:00', N'PGS.TS. Nguyễn Thanh Hải', 35, 'DA_GUI'),
(7, 'TB007', N'Mời Họp Tư vấn Học vụ Đối với Sinh viên Thuộc Diện Nguy cơ Buộc Thôi Học (Mức 3)', N'Kính gửi Quý Phụ huynh và các em sinh viên có tên trong danh sách cảnh báo mức 3. Buổi làm việc trực tiếp diễn ra tại Phòng Hội thảo A1.', 'CANH_BAO', NULL, NULL, '2024-12-01 09:30:00', N'Hội Đồng Học Vụ Nhà Trường', 45, 'DA_GUI'),
(8, 'TB008', N'Hướng dẫn Đăng ký Học phần Kỳ 2 Năm học 2024-2025 theo Khung 150 Tín chỉ', N'Sinh viên lưu ý đối soát tín chỉ tích lũy, đặc biệt sinh viên năm 4 cần hoàn thành trên 120 tín chỉ để đủ điều kiện xét làm đồ án tốt nghiệp.', 'CHUNG', NULL, NULL, '2024-12-20 15:00:00', N'Phòng Đào Tạo', 1050, 'DA_GUI'),
(9, 'TB009', N'Thông báo Cảnh báo Học vụ & Lịch Hẹn Tư vấn Cá nhân - SV 20230122', N'Gửi sinh viên Hồ Thu Trang (20230122) - Lớp DCCNTT14A: Bạn đang thuộc diện cảnh báo học vụ. Yêu cầu bạn liên hệ cố vấn học tập để thực hiện buổi tư vấn bắt buộc.', 'CANH_BAO', 'DCCNTT14A', '20230122', '2024-11-22 10:00:00', N'Cố Vấn Học Tập Phụ Trách', 1, 'DA_GUI'),
